/* global describe, it, expect -- Jest globals (the Expo ESLint config only declares them for TypeScript) */
const { execFileSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const { quoteBundleScript } = require('../withQuotedBundleScript');

// Tail of the "Bundle React Native code and images" phase generated by `expo prebuild` (SDK 57).
const TEMPLATE_TAIL = [
  'export SKIP_BUNDLING=1',
  '',
  "`\"$NODE_BINARY\" --print \"require('path').dirname(require.resolve('react-native/package.json')) + '/scripts/react-native-xcode.sh'\"`",
  '',
].join('\n');

/** Runs `script` with a fake node that prints a react-native-xcode.sh living under a path with a space. */
function runWithSpacedPath(script) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'roam '));
  const xcodeScript = path.join(root, 'Mouss coding', 'react-native-xcode.sh');
  fs.mkdirSync(path.dirname(xcodeScript));
  fs.writeFileSync(xcodeScript, '#!/bin/sh\necho bundled\n', { mode: 0o755 });
  const fakeNode = path.join(root, 'node');
  fs.writeFileSync(fakeNode, `#!/bin/sh\necho '${xcodeScript}'\n`, { mode: 0o755 });
  try {
    return execFileSync('/bin/sh', ['-c', script], {
      env: { ...process.env, NODE_BINARY: fakeNode },
      encoding: 'utf8',
      stdio: 'pipe',
    });
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
}

describe('quoteBundleScript', () => {
  it('quotes the react-native-xcode.sh invocation', () => {
    expect(quoteBundleScript(TEMPLATE_TAIL)).toContain(
      '"$("$NODE_BINARY" --print "require(\'path\').dirname(require.resolve(\'react-native/package.json\')) + \'/scripts/react-native-xcode.sh\'")"',
    );
  });

  it('returns null when there is nothing to quote (already patched or template changed)', () => {
    expect(quoteBundleScript(quoteBundleScript(TEMPLATE_TAIL))).toBeNull();
    expect(quoteBundleScript('echo nothing')).toBeNull();
  });

  it('runs a script whose path contains a space (e.g. "Mouss coding")', () => {
    expect(() => runWithSpacedPath(TEMPLATE_TAIL)).toThrow();
    expect(runWithSpacedPath(quoteBundleScript(TEMPLATE_TAIL))).toBe('bundled\n');
  });
});
